Here is the root cause:
The old_wi_state pointer was only fetched inside the `if (!input)` block, leaving it NULL when writing "true" (enabling auto-tuning). This caused the cleanup path to skip freeing the old state after `rcu_assign_pointer()` replaced it, because the cleanup was gated on `old_wi_state != NULL`. Additionally, when writing "false" and the current mode was already manual, the early return before the fetch left `new_wi_state` unfreed. Moving the fetch before the input check ensures `old_wi_state` is always available for proper cleanup and early return logic.

Here is the patch:

 static ssize_t weighted_interleave_auto_store(struct kobject *kobj,
 		struct kobj_attribute *attr, const char *buf, size_t count)
 {
 	struct weighted_interleave_state *new_wi_state, *old_wi_state = NULL;
 	unsigned int *bw;
 	bool input;
 	int i;

 	if (kstrtobool(buf, &input))
 		return -EINVAL;

 	new_wi_state = kzalloc_flex(*new_wi_state, iw_table, nr_node_ids);
 	if (!new_wi_state)
 		return -ENOMEM;
 	for (i = 0; i < nr_node_ids; i++)
 		new_wi_state->iw_table[i] = 1;

 	mutex_lock(&wi_state_lock);
-	if (!input) {
-		old_wi_state = rcu_dereference_protected(wi_state,
-					lockdep_is_held(&wi_state_lock));
-		if (!old_wi_state)
-			goto update_wi_state;
-		if (input == old_wi_state->mode_auto) {
-			mutex_unlock(&wi_state_lock);
-			return count;
-		}
+	old_wi_state = rcu_dereference_protected(wi_state,
+				lockdep_is_held(&wi_state_lock));

-		memcpy(new_wi_state->iw_table, old_wi_state->iw_table,
-					       nr_node_ids * sizeof(u8));
+	if (old_wi_state && input == old_wi_state->mode_auto) {
+		mutex_unlock(&wi_state_lock);
+		kfree(new_wi_state);
+		return count;
+	}
+
+	if (!input) {
+		if (old_wi_state)
+			memcpy(new_wi_state->iw_table, old_wi_state->iw_table,
+						       nr_node_ids * sizeof(u8));
 		goto update_wi_state;
 	}

 	bw = node_bw_table;
 	if (!bw) {
 		mutex_unlock(&wi_state_lock);
 		kfree(new_wi_state);
 		return -ENODEV;
 	}

 	new_wi_state->mode_auto = true;
 	reduce_interleave_weights(bw, new_wi_state->iw_table);

 update_wi_state:
 	rcu_assign_pointer(wi_state, new_wi_state);
 	mutex_unlock(&wi_state_lock);
 	if (old_wi_state) {
 		synchronize_rcu();
 		kfree(old_wi_state);
 	}
 	return count;
 }



